function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function fetchUser() {
  console.log('Fetching...');
  await delay(1000);
  console.log('User loaded');
  return { name: 'Alice' };
}

async function main() {
  console.log('Start');
  const user = await fetchUser();
  console.log('Got:', user.name);
  console.log('End');
}

main();
